package org.nigeriag2p.field;
import android.app.job.*;import android.content.*;import org.json.*;import java.io.*;import java.net.*;import java.util.*;
public class UploadJob extends JobService {
 static final int NOW=10441, PERIODIC=10442;static final Object UPLOAD_LOCK=new Object();
 static void schedule(Context context){JobScheduler scheduler=(JobScheduler)context.getSystemService(Context.JOB_SCHEDULER_SERVICE);ComponentName name=new ComponentName(context,UploadJob.class);scheduler.schedule(new JobInfo.Builder(NOW,name).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPersisted(true).setBackoffCriteria(30000,JobInfo.BACKOFF_POLICY_EXPONENTIAL).build());scheduler.schedule(new JobInfo.Builder(PERIODIC,name).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(15*60*1000L).setPersisted(true).build());}
 public boolean onStartJob(JobParameters params){new Thread(()->{boolean retry=runQueue();jobFinished(params,retry);}).start();return true;}
 public boolean onStopJob(JobParameters params){return true;}
 static String esc(String x){return x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
 static String tag(String n,String x){return "<"+n+">"+esc(x)+"</"+n+">";}
 static String xml(JSONObject r){String lat=r.optString("lat"),lon=r.optString("lon"),accuracy=r.optString("accuracy");return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><data id=\"nsipa_field_household_demo\" version=\"2026110401\"><visit>"+tag("enumerator_id",r.optString("officer"))+tag("visit_date",r.optString("date"))+tag("consent","yes")+"</visit><location>"+tag("state",r.optString("state"))+tag("lga",r.optString("lga"))+tag("ward",r.optString("ward"))+(lat.isEmpty()?"":tag("coordinates",lat+" "+lon+" 0 "+(accuracy.isEmpty()?"0":accuracy)))+"</location><household>"+tag("sample_reference",r.optString("ref"))+tag("household_size",r.optString("size"))+tag("children",r.optString("children"))+tag("shelter",r.optString("shelter"))+"</household><livelihood>"+tag("livelihood_type",r.optString("livelihood"))+tag("priority_needs",r.optString("need"))+"</livelihood><review>"+tag("review_confirmation","yes")+"</review><meta>"+tag("instanceID",r.optString("id"))+tag("instanceName","SAMPLE "+r.optString("ref"))+"</meta></data>";}
 static int post(String endpoint,String xml)throws Exception {String boundary="Field"+UUID.randomUUID().toString().replace("-","");HttpURLConnection c=(HttpURLConnection)new URL(endpoint+"/submission").openConnection();try{c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("X-OpenRosa-Version","1.0");c.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);try(OutputStream out=c.getOutputStream()){out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"xml_submission_file\"; filename=\"submission.xml\"\r\nContent-Type: text/xml; charset=utf-8\r\n\r\n").getBytes("UTF-8"));out.write(xml.getBytes("UTF-8"));out.write(("\r\n--"+boundary+"--\r\n").getBytes("UTF-8"));}return c.getResponseCode();}finally{c.disconnect();}}
 boolean runQueue(){synchronized(UPLOAD_LOCK){try{JSONObject all; synchronized(FieldStore.LOCK){all=FieldStore.read(this);}String endpoint=all.optString("endpoint");if(!endpoint.startsWith("https://"))return false;JSONArray entries=all.getJSONArray("records");boolean retry=false;for(int i=0;i<entries.length();i++){JSONObject item=entries.getJSONObject(i);if(!"approved-demo".equals(item.optString("status")))continue;String id=item.optString("id"),error="";try{int code=post(endpoint,xml(item));if(code!=201)error="HTTP "+code;}catch(Exception e){error="Connection failed";}synchronized(FieldStore.LOCK){JSONObject latest=FieldStore.read(this);JSONArray live=latest.getJSONArray("records");for(int j=0;j<live.length();j++){JSONObject row=live.getJSONObject(j);if(id.equals(row.optString("id"))&&"approved-demo".equals(row.optString("status"))){if(error.isEmpty()){row.put("status","sent");row.remove("sync_error");}else row.put("sync_error",error);break;}}FieldStore.write(this,latest);}if(!error.isEmpty())retry=true;}return retry;}catch(Exception e){return true;}}}
}
